import{_ as a}from"./chunks/04.Ch-ZqWLj.js";import{_ as t,o,c as n,aa as r}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/cs/diary/ciselnik_osoby.png",v=JSON.parse('{"title":"Číselníky deníku","description":"","frontmatter":{"title":"Číselníky deníku"},"headers":[],"relativePath":"diary/codelists.md","filePath":"diary/codelists.md","lastUpdated":1794209661000}'),s={name:"diary/codelists.md"};function l(d,e,p,c,k,m){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ciselniky-deniku" tabindex="-1">Číselníky deníku <a class="header-anchor" href="#ciselniky-deniku" aria-label="Permalink to &quot;Číselníky deníku&quot;">​</a></h1><p>V číselnících si pro stavbu dopředu připravíte, co se bude v deníku nabízet: kategorie Dalších záznamů a seznamy osob, mechanizmů a materiálů. Číselníky jsou nepovinné, ale zrychlí zapisování a sjednotí podobu záznamů.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/osoby-mechanizmy">Zapsat osoby, stroje a materiál</a> a <a href="/buildary-help-preview/akademie/dalsi-zaznamy">Zapsat výzvu, kontrolu nebo připomínku</a> v Akademii.</p><h2 id="kde-ciselniky-najdete" tabindex="-1">Kde číselníky najdete <a class="header-anchor" href="#kde-ciselniky-najdete" aria-label="Permalink to &quot;Kde číselníky najdete&quot;">​</a></h2><p>Otevřete <strong>Nastavení stavby</strong> a záložku <strong>Číselníky - Stavební deník</strong>. Číselníky platí pro celou stavbu. Upravovat je smí ten, kdo má na stavbě kompetenci <strong>Administrace stavby</strong> – viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><table tabindex="0"><thead><tr><th>Číselník</th><th>Kde se v deníku nabízí</th></tr></thead><tbody><tr><td><strong>Kategorie dalších záznamů</strong></td><td>Pole <strong>Kategorie</strong> u <a href="/buildary-help-preview/diary/dailyentriesothers">Dalšího záznamu</a>.</td></tr><tr><td><strong>Osoby na staveništi</strong></td><td>Sekce Osoby v <a href="/buildary-help-preview/diary/dailyentriespersons">denních záznamech</a>.</td></tr><tr><td><strong>Mechanizmy</strong></td><td>Sekce Mechanizmy.</td></tr><tr><td><strong>Materiály, výrobky a technologické dodávky</strong></td><td>Sekce Materiály.</td></tr></tbody></table><p>Pokud stavba vznikla podle <a href="/buildary-help-preview/diary/projectsetup#vzorova-stavba">vzorové stavby</a> nebo <a href="/buildary-help-preview/diary/projectsetup#nova-stavba-kopirovanim">kopírováním</a>, převezme číselníky z ní.</p><h2 id="kategorie-dalsich-zaznamu" tabindex="-1">Kategorie Dalších záznamů <a class="header-anchor" href="#kategorie-dalsich-zaznamu" aria-label="Permalink to &quot;Kategorie Dalších záznamů&quot;">​</a></h2><p>Podle kategorií se Další záznamy třídí a filtrují. Číselník je předvyplněný, například kategoriemi <strong>Předání a převzetí pracoviště</strong>, <strong>Technické kontroly, zkoušky a měření</strong>, <strong>Výzva ke kontrole zakrývaných prací</strong>, <strong>Změny</strong> nebo <strong>Ostatní</strong>. Kategorie můžete přidávat a upravovat podle potřeb stavby.</p><figure class="shot" style="--w:640px;"><img src="'+a+'" alt="Výběr kategorie při přidání Dalšího záznamu" loading="lazy"><figcaption>Kategorie z číselníku se nabízí při zápisu Dalšího záznamu.</figcaption></figure><h2 id="osoby-mechanizmy-a-materialy" tabindex="-1">Osoby, mechanizmy a materiály <a class="header-anchor" href="#osoby-mechanizmy-a-materialy" aria-label="Permalink to &quot;Osoby, mechanizmy a materiály&quot;">​</a></h2><p>Když tyto seznamy naplníte, budou se jejich položky nabízet při zápisu v příslušné sekci deníku. Položky přidáte dvěma způsoby:</p><ul><li>jednotlivě tlačítkem <strong>Přidat</strong>,</li><li>najednou z excelového souboru tlačítkem <strong>Importovat excel</strong>.</li></ul><figure class="shot" style="--w:640px;"><img src="'+i+'" alt="Nápověda u tlačítka Importovat excel s požadovanými názvy sloupců" loading="lazy"></figure><p>Pro import platí:</p><ul><li>Seznam musí být na <strong>prvním listu</strong> souboru.</li><li>Sloupce musí mít <strong>přesné názvy</strong>, které aplikace očekává. Zobrazí se, když najedete myší na tlačítko <strong>Importovat excel</strong> – pro osoby jsou to například <code>Name</code>, <code>Profession</code>, <code>Contractor</code>.</li><li>Nemusíte uvést všechny sloupce a nezáleží na jejich pořadí, jen na názvech.</li></ul><div class="info custom-block"><p class="custom-block-title">Číselníky nejsou povinné</p><p>S číselníky i bez nich můžete do deníku psát volně. Co jednou zapíšete, se vám příště samo nabídne.</p></div><h2 id="souvisejici-ciselniky" tabindex="-1">Související číselníky <a class="header-anchor" href="#souvisejici-ciselniky" aria-label="Permalink to &quot;Související číselníky&quot;">​</a></h2><ul><li><strong>Role firem</strong> a <strong>Role členů</strong> jsou v projektovém týmu – viz <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</li><li><strong>Číselníky - Management úkolů</strong> (kategorie úkolů, štítky, pravidla pro Řešitele a Schvalovatele) – krok za krokem: <a href="/buildary-help-preview/akademie/ciselniky">Upravit kategorie a štítky úkolů</a> v Akademii.</li></ul>',19)])])}const h=t(s,[["render",l]]);export{v as __pageData,h as default};
